import {EVALUATION_CASES,controlCandidates} from './evaluation-fixtures.mjs';
import {parseEvaluation} from './evaluation-core.mjs';
import {analysisScenario,matchesAnalysisSource} from './analysis-core.mjs';
import {createAnalysisCase,attachAnalysisCandidate,considerAnalysis,analysisIsCurrent,documentIsCurrent} from './threat-core.mjs';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
export function analysisDesk({getWorkspace,getSelected,applyWorkspace,selectCase,uid,today,feedback}){
  let scenarioId='dev-conflict',canAttach=false,busy=false,config={enabled:false},inputText='',reviewNotes=new Map(),generation=0;
  const hasDraft=()=>!!inputText.trim()||[...reviewNotes.values()].some(v=>v.trim());
  function availability(){if(!$('analysis-generate'))return;$('analysis-generate').disabled=busy||!canAttach||!config.enabled||config.busy||config.remaining<1;$('analysis-config').textContent=(config.enabled?`${config.notice} Model: ${config.model}. ${config.remaining} request attempts remain.`:config.notice)||'Inspect sources and attach saved candidate JSON. Live execution requires the configured local runner.';}
  async function status(){const request=++generation;if(location.hostname!=='127.0.0.1'){config={enabled:false,notice:'Hosted preview: attach a saved synthetic draft. Live generation is available on the configured local runner.'};availability();return;}try{const r=await fetch('/api/ai/status');if(!r.ok)throw new Error();const next=await r.json();if(request!==generation)return;config=next;}catch{config={enabled:false};}availability();}
  function render(){
    const w=getWorkspace(),scenario=analysisScenario(scenarioId),c=w.assessments.find(c=>c.id===getSelected()),matches=c?.question===scenario.question;
    canAttach=matches;const runs=matches?w.analysisRuns.filter(r=>r.assessmentId===c.id):[];
    $('content').innerHTML=`<section class="panel"><div class="panel-heading"><div><h2>Case analysis</h2><span class="muted">Question → selected reports → cited draft → analyst case</span></div></div><div class="analysis-layout"><div class="case-body"><label for="analysis-scenario">Fictional intelligence question</label><select id="analysis-scenario" ${busy?'disabled':''}>${EVALUATION_CASES.map(s=>`<option value="${s.id}" ${s.id===scenarioId?'selected':''}>${esc(s.category)} / ${s.split==='holdout'?'Reserved':'Development'}</option>`).join('')}</select><h3>${esc(scenario.question)}</h3><p class="muted">${scenario.documents.length} selected fictional report${scenario.documents.length===1?'':'s'}. This prototype sends only these bundled inputs to a model.</p>${scenario.documents.map(d=>{const bound=matches?w.documents.find(x=>x.assessmentId===c.id&&documentIsCurrent(w,x.id)&&matchesAnalysisSource(x,d)):null;const evidence=bound?w.evidence.find(e=>e.sourceDocumentId===bound.id):null;return `<article class="analysis-source"><p class="small-label">${esc(d.id)}${bound?` → ${esc(bound.id)}`:''}</p><h3>${esc(d.publisher)}</h3><p class="muted">${esc(d.language)} · ${d.reportedAt} · Source group: ${esc(d.originGroup)}</p><blockquote class="source-excerpt">${esc(d.excerpt)}</blockquote>${bound?evidence?`<p class="muted">Source-linked evidence: ${esc(evidence.id)} / ${esc(evidence.claimState)} / ${esc(evidence.relation)}</p>`:`<button data-incorporate="${bound.id}" ${busy?'disabled':''}>Review this source for evidence</button>`:''}</article>`;}).join('')}<label for="analysis-target">Case for this question</label><select id="analysis-target" ${busy?'disabled':''}><option value="">Create a new case below</option>${w.assessments.filter(x=>x.question===scenario.question).map(x=>`<option value="${x.id}" ${x.id===c?.id?'selected':''}>${esc(x.title)} / ${esc(x.id)}</option>`).join('')}</select><div class="dialog-grid"><div><label for="analysis-area">Case area</label><input id="analysis-area" maxlength="150" value="${esc(matches?c.area:'India / fictional training context')}" ${busy?'disabled':''}></div><div><label for="analysis-scope">Case scope</label><select id="analysis-scope" ${busy?'disabled':''}>${['Domestic','Cross-border','International'].map(scope=>`<option ${matches&&c.scope===scope?'selected':''}>${scope}</option>`).join('')}</select></div></div><div class="actions"><button id="analysis-create" ${busy?'disabled':''}>Create case with selected reports</button>${matches?`<button data-task-case="${c.id}">Open assessment</button>`:''}</div></div><div class="case-body analysis-work"><h3>${matches?'Drafts for this case':'Prepare the analyst case'}</h3><p class="notice">${matches?`${esc(c.title)} · ${c.status} · ${runs.length} analytical draft${runs.length===1?'':'s'}`:'Create a case to retain the question, reports and analytical drafts together.'}</p><p id="analysis-config" class="muted"></p><label class="checkline"><input id="analysis-api-ack" type="checkbox" ${busy?'disabled':''}><span>I approve one API request using the fictional inputs shown here.</span></label><div class="actions"><button id="analysis-generate" class="primary" disabled>Generate draft for this case</button><button id="analysis-saved" ${busy||!matches?'disabled':''}>Load saved AI draft (no API cost)</button><button id="analysis-control" ${busy||!matches?'disabled':''}>Try authored example — no AI call</button></div><details ${inputText?'open':''}><summary>Attach an existing synthetic AI draft</summary><label for="analysis-json">Candidate JSON from the AI runner</label><textarea id="analysis-json" rows="5" maxlength="2000000" ${busy?'disabled':''}>${esc(inputText)}</textarea><div class="actions"><button id="analysis-import" ${busy||!matches?'disabled':''}>Validate & attach draft</button><button id="analysis-discard" ${busy?'disabled':''}>Clear pasted JSON and notes</button></div></details><p class="muted">Drafts retain exact citations to every selected report. Attachment and consideration leave evidence and analyst judgment unchanged. Origin labels on imported files are unverified.</p>${runs.map(r=>runCard(w,r)).join('')||'<p class="empty">No analytical draft in this case yet.</p>'}</div></div></section>`;
    $('analysis-scenario').addEventListener('change',e=>{if(hasDraft()){e.target.value=scenarioId;feedback('Attach or clear the pasted JSON and record or clear review notes before changing questions.',true);return;}scenarioId=e.target.value;render();});
    $('analysis-target').addEventListener('change',e=>{if(hasDraft()){render();feedback('Record or clear the current draft notes first.',true);return;}selectCase(e.target.value||null);render();});
    $('analysis-json').addEventListener('input',e=>{inputText=e.target.value;});
    $('analysis-discard').addEventListener('click',()=>{inputText='';reviewNotes.clear();render();feedback('Unapplied JSON and analysis notes cleared. Recorded drafts are retained.');});
    $('analysis-create').addEventListener('click',()=>{try{if(hasDraft())throw new Error('Attach or clear pasted JSON and review notes before creating another case.');const assessmentId=uid('case'),next=createAnalysisCase(getWorkspace(),{scenarioId,assessmentId,documentIds:scenario.documents.map(()=>uid('doc')),scope:$('analysis-scope').value,area:$('analysis-area').value},today());applyWorkspace(next);selectCase(assessmentId);render();feedback('Case created with the question and all selected reports. No evidence or AI output added. Save workspace to retain it.');}catch(e){feedback(e.message,true);}});
    $('analysis-import').addEventListener('click',()=>attach(parseEvaluationSafe(inputText),'Imported candidate'));
    $('analysis-saved').addEventListener('click',async()=>{if(busy)return;try{const r=await fetch(`./examples/${scenario.split==='holdout'?'reserved':'development'}-candidates.json`);if(!r.ok)throw new Error('Saved example could not be loaded.');await attach(await r.json(),'Imported candidate');}catch(e){feedback(e.message,true);}});
    $('analysis-control').addEventListener('click',()=>attach(controlCandidates(scenario.split,'faithful'),'Authored control'));
    $('analysis-generate').addEventListener('click',generate);
    document.querySelectorAll('[data-analysis-note]').forEach(e=>e.addEventListener('input',()=>reviewNotes.set(e.dataset.analysisNote,e.value)));
    document.querySelectorAll('[data-analysis-decision]').forEach(e=>e.addEventListener('click',()=>{try{const note=reviewNotes.get(e.dataset.analysisRun)||'';applyWorkspace(considerAnalysis(getWorkspace(),e.dataset.analysisRun,{status:e.dataset.analysisDecision,reviewNote:note},today()));reviewNotes.delete(e.dataset.analysisRun);render();feedback('Consideration recorded. Evidence and analyst judgment unchanged. Save workspace to retain the note.');}catch(err){feedback(err.message,true);}}));
    availability();status();
  }
  function parseEvaluationSafe(raw){try{return parseEvaluation(raw);}catch(e){feedback(e.message,true);return null;}}
  function runCard(w,r){const current=analysisIsCurrent(w,r);return `<article class="analysis-run"><p class="small-label">${esc(r.id)} / ${r.createdAt}</p><h3>${r.kind==='Authored control'?'Authored example — no AI called':'Analytical draft'}</h3><div class="tags"><span class="tag">${r.status}</span><span class="tag">${current?'Current inputs':'Stale inputs'}</span></div><p class="muted">${esc(r.kind)} · ${esc(r.candidateLabel)} · Labels unverified</p>${!current?'<p class="error">The assessment or a selected source changed. This retained draft cannot be marked Considered. Reject it and generate or attach a new draft using current inputs.</p>':''}${r.output.abstention?`<h3>Abstention</h3><p>${esc(r.output.abstention)}</p>`:r.output.proposals.map(p=>`<h3>Attributed draft</h3><p class="proposal-statement">${esc(p.draftStatement)}</p><p class="muted">Limitations: ${esc(p.limitations)}</p>${r.status==='Considered'?`<button data-prepare-judgment="${r.id}" data-draft-proposal="${p.id}" ${!current||busy?'disabled':''}>Prepare assessment from this draft</button>`:''}${p.citations.map(q=>{const d=r.snapshot.sources.find(s=>s.documentId===q.documentId).document;return `<p class="small-label">${esc(d.publisher)} / ${esc(d.id)} / ${esc(q.documentId)} / UTF-16 [${q.start}, ${q.end})</p><blockquote class="source-excerpt">${esc(q.quote)}</blockquote>`;}).join('')}`).join('')}${r.status==='Pending'?`<label for="analysis-note-${r.id}">Analyst consideration note</label><textarea id="analysis-note-${r.id}" data-analysis-note="${r.id}" maxlength="2000" rows="2" ${busy?'disabled':''}>${esc(reviewNotes.get(r.id)||'')}</textarea><div class="actions"><button data-analysis-decision="Considered" data-analysis-run="${r.id}" ${!current||busy?'disabled':''}>Record consideration</button><button data-analysis-decision="Rejected" data-analysis-run="${r.id}" ${busy?'disabled':''}>Reject draft</button></div>`:`<p>Consideration note: ${esc(r.reviewNote)} · ${r.reviewedAt}</p>`}<p class="muted">Considered records a human note; it does not establish semantic accuracy or agency approval.</p></article>`;}
  async function attach(candidates,kind){if(!candidates||busy)return;if(kind!=='Imported candidate'&&inputText.trim()){feedback('Attach or clear pasted JSON before loading another draft.',true);return;}const original=getWorkspace(),assessmentId=getSelected();busy=true;render();try{if(!assessmentId)throw new Error('Create or select the case first.');const next=await attachAnalysisCandidate(original,assessmentId,scenarioId,candidates,uid('analysis'),today(),kind);if(getWorkspace()!==original)throw new Error('Workspace changed during validation. Retry against the current case.');applyWorkspace(next);inputText='';feedback(`${kind} attached to the case with validated source spans. Save workspace to retain it.`);}catch(e){feedback(e.message,true);}finally{busy=false;render();}}
  async function generate(){if(busy)return;if(!$('analysis-api-ack').checked){feedback('Approve the single fictional API request first.',true);return;}const original=getWorkspace(),assessmentId=getSelected(),scenario=analysisScenario(scenarioId);if(!assessmentId||original.assessments.find(c=>c.id===assessmentId)?.question!==scenario.question){feedback('Create or select the case for this question first.',true);return;}
    // Fail closed before spending: require the complete current authored input set.
    if(scenario.documents.some(source=>original.documents.filter(d=>d.assessmentId===assessmentId&&documentIsCurrent(original,d.id)&&matchesAnalysisSource(d,source)).length!==1)){feedback('Current selected reports differ from the bundled inputs. Create a new fictional case for this request.',true);return;}
    busy=true;render();try{const response=await fetch('/api/ai/analyze',{method:'POST',headers:{'Content-Type':'application/json','X-Ruthless-Request':'ai-console-v1'},body:JSON.stringify({split:scenario.split,caseId:scenario.id,allowApi:true})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Analysis request failed.');inputText=JSON.stringify(result.candidates,null,2);if(result.mode==='Mocked integration test')throw new Error('Mocked provider result retained as JSON; no AI called. Attach it as an imported candidate if needed.');const next=await attachAnalysisCandidate(original,assessmentId,scenario.id,result.candidates,uid('analysis'),today(),'Local API execution');if(getWorkspace()!==original)throw new Error('Workspace changed during the request. Output retained in the JSON field for manual attachment.');applyWorkspace(next);inputText='';feedback('AI draft attached with exact source citations. Evidence and judgment await analyst work.');}catch(e){feedback(e.message,true);}finally{busy=false;render();}}
  return {render,hasDraft,reset:()=>{inputText='';reviewNotes.clear();generation++;},isBusy:()=>busy,selectFromCase:assessmentId=>{const c=getWorkspace().assessments.find(c=>c.id===assessmentId),scenario=EVALUATION_CASES.find(s=>s.question===c?.question);if(scenario)scenarioId=scenario.id;}};
}
